/* global test expect */
import { DateTime } from "../../src/luxon";

function daysFromCivil(y, m, d) {
  y -= m <= 2 ? 1 : 0;
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}
function civilFromDays(z) {
  z += 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe/1460) + Math.floor(doe/36524) - Math.floor(doe/146096)) / 365);
  const y = yoe + era * 400;
  const doy = doe - (365*yoe + Math.floor(yoe/4) - Math.floor(yoe/100));
  const mp = Math.floor((5*doy + 2)/153);
  const d = doy - Math.floor((153*mp+2)/5) + 1;
  const m = mp + (mp < 10 ? 3 : -9);
  return [y + (m <= 2 ? 1 : 0), m, d];
}

test("plus across 100 barrier via February", () => {
  const bad = [];
  for (const start of ["0099-11-01","0099-12-01","0099-12-31","0100-01-01","0099-01-01","0100-02-01","0099-02-01"]) {
    for (let n = 0; n <= 120; n++) {
      const d = DateTime.fromISO(start).plus({ days: n });
      const [y, m, dd] = civilFromDays(daysFromCivil(+start.slice(0,4), +start.slice(5,7), +start.slice(8,10)) + n);
      if (d.year !== y || d.month !== m || d.day !== dd) {
        bad.push(`${start}+${n}d => ${d.toISODate()} expected ${y}-${String(m).padStart(2,"0")}-${String(dd).padStart(2,"0")}`);
      }
    }
  }
  console.log(bad.slice(0, 40).join("\n"), "\ntotal bad:", bad.length);
});
